        public async Awaitable OnEnterAsync(VisualElement screenRoot)
        {
            int generation = ++_generation;
            _root = screenRoot;
            _entryScope = _router.EntryFlow?.CallbackScope;
            _finished = false;
            _lastShownPrefix = null;
            _actors.Clear();
            _prevSpeaker = null;
            _line = null;
            _backgroundPath = null;
            _runner = null;
            _waitLeft = -1f;
            _reviewSeekComplete = false;
            _rebuilt = _router.EntryFlow?.InReading == true || IsRebuiltStory(System.IO.Path.GetFileNameWithoutExtension(_router.Session.ActiveStoryPath));
            string path = _router.Session.ActiveStoryPath;
            string json;
            try
            {
                json = _router.Session.ActiveStoryJson ?? await _router.Patch.ReadTextAsync(path);
                if (generation != _generation) return;
                _scene = JsonUtility.FromJson<StorySceneDto>(json) ?? throw new InvalidOperationException("empty scene");
            }
            catch (Exception e)
            {
                if (generation != _generation) return;
                if (_rebuilt)
                {
                    _scene = null;
                    BuildRebuilt(screenRoot);
                    ShowLoadFailure(false);
                    Debug.LogWarning("[Story] Story data unavailable: " + e.Message);
                    return;
                }
                Debug.LogError($"[Story] '{path}' could not load: {e.Message}");
                UomdUiKit.ShowToast(screenRoot, "The story could not be loaded.");
                await _router.EntryFlow.StoryFinishedAsync();
                return;
            }
            _cutscene = json.Contains("\"presentation\"");
            _auto = _cutscene && _scene.presentation != null && _scene.presentation.auto;
            if (_rebuilt && _router.EntryFlow != null && _router.EntryFlow.StageIndex > 0) _auto = _router.EntryFlow.Continuity.State.AutoRead;
            _skip = false;
            var entrySave = _router.EntryFlow != null && _router.EntryFlow.StageIndex > 0 && !_router.Session.IsReplayingIntro
                ? _router.EntryFlow.Continuity.RestoreStory(path, json, _scene) : null;
            _runner = new StoryRunner(_scene, entrySave);
            _lastLineId = LastLineId(_scene);
            if (_rebuilt)
            {
                BuildRebuilt(screenRoot);
                await LoadRebuiltImagesAsync(generation);
                return;
            }
#if UNITY_EDITOR
            if (PortraitReview)
            {
                foreach (string character in new[] { "fadyme", "mahmut" })
                {
                    var texture = await _router.Media.TextureAsync(PortraitPath(character, "composed"));
                    if (generation != _generation) return;
                    if (texture == null) throw new InvalidOperationException("Portrait master failed to load: " + character);
                }
                if (_router.ProductionPreview.PortraitVariant == "authored")
                {
                    foreach (var command in _scene.commands)
                    {
                        string character = command.op == "show" ? command.character : command.speaker;
                        if (character != "fadyme" && character != "mahmut") continue;
                        string portrait = PortraitPath(character, command.emotion);
                        var texture = await _router.Media.TextureAsync(portrait);
                        if (generation != _generation) return;
                        if (texture == null) throw new InvalidOperationException("Rebuilt emotion failed to load: " + character + "/" + command.emotion);
                    }
                }
                await _router.Media.TextureAsync(_router.Media.Catalog.Background(_scene.location_id));
                if (generation != _generation) return;
            }
#endif
            Build(screenRoot);
            SetBackground(_scene.location_id);
            Pump();
        }

        private static string LastLineId(StorySceneDto scene)
        {
            for (int i = scene.commands.Length - 1; i >= 0; i--)
            {
                var c = scene.commands[i];
                if (c != null && (c.op == "say" || c.op == "narrate")) return c.line_id;
            }
            return "";
        }

